}

export function trebolFactory<T extends (...args: any[]) => any>(loadFactory: () => Promise<{ default: T }>): T {
  return (async (...args: Parameters<T>) => {
    if (trebolMode() === "off") return;
    const { default: factory } = await loadFactory();
    await factory(...args);
  }) as T;
}

