			target: { kind: "question" },
			question: questionContext,
			answered,
			answer: serializedAnswer,
			note: answer.note,
		});
	}

	for (const [value, note] of Object.entries(answer.optionNotes ?? {})) {
		const option = getQuestionOptionByValue(question, value);
		if (!(option && note)) {
			continue;
		}

		items.push({
			target: {
				kind: "option",
				optionValue: value,
